pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address token = address(new TokenReverter());
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;

        bool ok = false;
        try c.transfer(address(this), token, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract TokenReverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always fail");
    }
}
